// Throwaway: run cases against the clone and diff with policy. Usage: tsx diff.ts <dir> <out.json> [ids...]
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createServer } from "node:net";
import { startCloneProcess } from "/work/harness/src/clone-process.ts";
import { diff, blocking, PolicySchema } from "/work/harness/src/policy.ts";
import adapter from "/work/targets/stripe-billing/adapter.ts";

const [dir = "", out = "", ...ids] = process.argv.slice(2);
const policy = PolicySchema.parse(
  JSON.parse(readFileSync("/work/targets/stripe-billing/policy.json", "utf8")),
);
const port: number = await new Promise((r) => {
  const s = createServer();
  s.listen(0, () => {
    const a = s.address();
    const p = typeof a === "object" && a ? a.port : 0;
    s.close(() => r(p));
  });
});
const clone = await startCloneProcess("stripe-billing", adapter.cloneEntry, port);
const url = `http://127.0.0.1:${String(port)}`;
const files = ids.length
  ? ids.map((i) => `${i}.json`)
  : readdirSync(dir).filter((f) => f.endsWith(".json") && f !== "failures.json");
const results: unknown[] = [];
for (const f of files) {
  const fx = JSON.parse(readFileSync(join(dir, f), "utf8"));
  try {
    await fetch(`${url}/__reset`, { method: "POST" });
    const actual = await adapter.run({ id: fx.id, input: fx.input } as never, { kind: "clone", url });
    const d = blocking(diff(policy, fx.observed, actual as never));
    results.push({ id: fx.id, n: d.length, diffs: d });
  } catch (e) {
    results.push({ id: fx.id, crash: String(e) });
  }
}
writeFileSync(out, JSON.stringify(results, null, 1));
await (clone as { stop?: () => Promise<void> }).stop?.();
process.exit(0);

